public class IntervalMergerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String merged(int[][] in) {
        try {
            return java.util.Arrays.deepToString(IntervalMerger.merge(in));
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    static Object covered(int[][] in) {
        try {
            return IntervalMerger.totalCovered(in);
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("merge unsorted overlapping", "[[1, 7]]", merged(new int[][] {{5, 7}, {1, 3}, {2, 6}}));
        check("touching intervals merge", "[[1, 5]]", merged(new int[][] {{1, 3}, {3, 5}}));
        check("gap is kept", "[[1, 3], [4, 5]]", merged(new int[][] {{1, 3}, {4, 5}}));
        check("contained interval swallowed", "[[1, 10]]", merged(new int[][] {{1, 10}, {2, 3}}));
        check("three groups",
                "[[0, 2], [3, 7], [8, 9], [20, 21]]",
                merged(new int[][] {{8, 9}, {3, 5}, {20, 21}, {0, 1}, {4, 7}, {1, 2}}));
        check("empty interval survives alone", "[[4, 4]]", merged(new int[][] {{4, 4}}));
        check("empty interval merges when touching", "[[1, 4]]", merged(new int[][] {{1, 4}, {4, 4}}));
        check("no rows", "[]", merged(new int[0][]));
        check("null input", "[]", merged(null));

        int[][] caller = {{5, 7}, {1, 3}, {2, 6}};
        IntervalMerger.merge(caller);
        check("caller array untouched", "[[5, 7], [1, 3], [2, 6]]", java.util.Arrays.deepToString(caller));

        check("totalCovered counts overlap once", 5, covered(new int[][] {{1, 3}, {2, 6}}));
        check("totalCovered with a gap", 7, covered(new int[][] {{0, 4}, {10, 13}}));
        check("totalCovered of nothing", 0, covered(null));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

